"use strict";

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');
const fs = require('fs');

// Initialize Express app
const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
});
app.use(limiter);

// CORS (adjust origins as needed)
app.use(cors({
  origin: ['https://trusted-domain.com'],
}));

// Body size limit
app.use(express.json({ limit: '10kb' }));

// HTTP request logging
app.use(morgan('combined'));

// Error logging
const errorLogStream = fs.createWriteStream('error.log', { flags: 'a' });

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  query('filter').optional().isString().trim().escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Error-handling middleware
app.use((err, req, res, next) => {
  errorLogStream.write(`${new Date().toISOString()} - ${err.stack}\n`);
  res.status(500).json({ error: 'Internal Server Error' });
});

// Unhandled promise rejections
process.on('unhandledRejection', (err) => {
  errorLogStream.write(`${new Date().toISOString()} - Unhandled Rejection: ${err}\n`);
  process.exit(1);
});

// Uncaught exceptions
process.on('uncaughtException', (err) => {
  errorLogStream.write(`${new Date().toISOString()} - Uncaught Exception: ${err}\n`);
  process.exit(1);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

